import {ShotCameraTransform} from './shot-camera-transform.js?v=20261027-pose-camera1';
import * as T from 'three';
import {configureShot,shotFov,focalFromShotFov} from './shot-camera-math.js?v=20261027-pose-camera1';
import {projectionFor,applyShotViewport} from './scene-projection.js?v=20261027-studio4';
import {fovToFocal} from './scene-lens.js?v=20261027-studio4';

export class SceneShotCamera{
 constructor(e){
  this.e=e;this.active=false;this.updating=false;
  const rail=document.querySelector('.camera-nav-rail'),view=document.getElementById('sceneView');
  const movement=document.createElement('button');movement.id='cameraMovement';movement.title='인물 움직임 · WASD';movement.setAttribute('aria-label','인물 움직임');movement.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="15" cy="4" r="2"/><path d="m5 9 5-2 4 3 4 1 3-2M13 9l-3 6 5 3-1 4M10 15l-4 4H2"/></svg>';rail.append(movement);movement.onclick=()=>{e.fly.finish(true);this.closePanel();document.getElementById('movementTab').click();};
  const button=document.createElement('button');button.id='cameraShot';button.title='촬영 카메라 만들기 · 카메라 화면';button.setAttribute('aria-label','촬영 카메라');button.setAttribute('aria-pressed','false');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="9" width="12" height="11" rx="2"/><circle cx="6" cy="5" r="3"/><circle cx="13" cy="5" r="3"/><path d="m15 12 6-3v11l-6-3Z"/></svg>';rail.append(button);this.button=button;
  const panel=document.createElement('section');panel.className='shot-camera-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','촬영 카메라 설정');
  panel.innerHTML='<header><b>촬영 카메라</b><button aria-label="카메라 설정 닫기">×</button></header><div class="shot-actions"><button id="shotView">카메라 화면</button><button id="shotAlign">현재 시점을 카메라에</button></div><label>초점거리 <span>mm</span><input id="shotFocal" aria-label="촬영 초점거리 mm" type="number" min="8" max="300" step="1"></label><label>화각 <span>세로 °</span><input id="shotFov" aria-label="촬영 화각" type="number" min="5" max="140" step="1"></label><label>Sensor Fit<select id="shotSensorFit" aria-label="Sensor Fit"><option value="auto">Auto · 긴 변</option><option value="horizontal">Horizontal · 가로</option><option value="vertical">Vertical · 세로</option></select></label><label>센서 크기 <span>mm</span><input id="shotSensorSize" aria-label="센서 크기 mm" type="number" min="1" max="100" step=".1"></label><label>화면 회전 <span>°</span><input id="shotRoll" aria-label="촬영 카메라 화면 회전" type="number" step="1"></label><p>테두리 선택 → R 회전 · X/Y 기울이기 · Z 화면 회전 · Enter 확정 / Esc 취소</p><p class="shot-dimensions"></p><details><summary>위치 · 방향</summary><div class="shot-coordinates"></div></details><button id="shotRender">이 카메라로 PNG 촬영</button><button id="shotRemove">카메라 제거</button><p>촬영 구도는 컷에 저장됩니다. 일반 화면으로 돌아가도 카메라는 그 자리에 남습니다.</p>';
  view.append(panel);this.panel=panel;
  this.frame=document.createElement('div');this.frame.className='shot-frame';this.frame.hidden=true;this.frame.innerHTML='<span>CAMERA</span>';view.append(this.frame);this.transform=new ShotCameraTransform(this,view);
  this.helperCamera=new T.PerspectiveCamera(45,1,.04,1);this.helper=new T.CameraHelper(this.helperCamera);this.helper.visible=false;this.helper.raycast=()=>{};this.helper.userData.editorOnly=true;e.scene.add(this.helper);
  const input=id=>panel.querySelector('#'+id);this.inputs={focal:input('shotFocal'),fov:input('shotFov'),fit:input('shotSensorFit'),size:input('shotSensorSize'),roll:input('shotRoll')};
  this.inputs.roll.onchange=()=>{if(Number.isFinite(this.inputs.roll.valueAsNumber))this.change({roll:this.inputs.roll.valueAsNumber});};
  this.inputs.focal.onchange=()=>this.change({focalLength:T.MathUtils.clamp(+this.inputs.focal.value||50,8,300)});
  this.inputs.fov.onchange=()=>this.change({focalLength:T.MathUtils.clamp(focalFromShotFov(T.MathUtils.clamp(+this.inputs.fov.value||45,5,140),this.data,this.aspect),8,300)});
  this.inputs.fit.onchange=()=>this.change({sensorFit:this.inputs.fit.value});this.inputs.size.onchange=()=>this.change({sensorSize:T.MathUtils.clamp(+this.inputs.size.value||36,1,100)});
  for(const input of Object.values(this.inputs))input.oninput=()=>{if(input.value&&input.validity.valid)input.onchange();};
  this.coords=[];for(const [key,label]of [['position','카메라'],['target','바라보는 점']]){const row=document.createElement('div');row.className='object-triple';row.append(document.createTextNode(label));for(let axis=0;axis<3;axis++){const field=document.createElement('input');field.type='number';field.step='.05';field.setAttribute('aria-label','촬영 '+label+' '+'XYZ'[axis]);row.append(field);this.coords.push({field,key,axis});field.onchange=()=>{if(!Number.isFinite(field.valueAsNumber))return;const values=[...this.data[key]];values[axis]=field.valueAsNumber;this.change({[key]:values});};}panel.querySelector('.shot-coordinates').append(row);}
  button.onclick=()=>{if(!e.isOpen||e.loading)return;e.fly.finish(true);e.movement.stop();e.figurePicker.close();e.advanced.skyPicker.close();if(!this.data)this.create();panel.hidden=false;if(!this.active)this.enter();this.sync();};
  panel.querySelector('header button').onclick=()=>this.closePanel();input('shotView').onclick=()=>this.active?this.exit():this.enter();input('shotAlign').onclick=()=>{if(!this.data)this.create();this.change({position:e.camera.position.toArray(),target:e.controls.target.toArray()});};input('shotRemove').onclick=()=>{this.exit();delete e.state.shotCamera;this.helper.visible=false;this.closePanel();e.queueLive();};input('shotRender').onclick=()=>this.render();
  panel.addEventListener('keydown',event=>{if(event.code==='Escape'){event.preventDefault();event.stopPropagation();this.closePanel();}});
 }
 get data(){return this.e.state?.shotCamera;}
 get aspect(){const r=projectionFor(this.e.cut,this.e.cut.pageWidth);return r.w/r.h;}
 create(){const e=this.e;e.state.shotCamera={position:e.camera.position.toArray(),target:e.controls.target.toArray(),focalLength:e.state.focalLength||fovToFocal(e.state.fov,this.aspect),sensorFit:'auto',sensorSize:36,roll:e.state.look?.roll||0};e.queueLive();}
 closePanel(){this.panel.hidden=true;}
 reset(){this.transform.deselect();this.active=false;this.before=null;this.frame.hidden=true;this.helper.visible=false;this.closePanel();this.button.setAttribute('aria-pressed','false');}
 enter(){if(!this.data||this.active)return;const e=this.e;e.flush();this.before={position:e.camera.position.clone(),target:e.controls.target.clone(),fov:e.state.fov,focalLength:e.state.focalLength};this.active=true;this.updating=true;configureShot(e.camera,this.data,this.aspect);e.controls.target.fromArray(this.data.target);e.controls.update();this.updating=false;this.frame.hidden=false;this.sync();e.resize();e.invalidate();}
 exit(){if(!this.active)return;this.transform.deselect();const e=this.e;this.track();this.active=false;this.frame.hidden=true;this.updating=true;e.camera.position.copy(this.before.position);e.controls.target.copy(this.before.target);e.state.fov=e.camera.fov=this.before.fov;if(this.before.focalLength)e.state.focalLength=this.before.focalLength;else delete e.state.focalLength;e.controls.update();this.updating=false;this.before=null;this.sync();e.resize();e.storeCamera();}
 track(){if(!this.active||this.updating||this.e.capturing||!this.data)return;this.data.position=this.e.camera.position.toArray();this.data.target=this.e.controls.target.toArray();this.sync();}
 change(values){if(!this.data)return;Object.assign(this.data,values);if(this.active){this.updating=true;configureShot(this.e.camera,this.data,this.aspect);this.e.controls.target.fromArray(this.data.target);this.e.controls.update();this.updating=false;}this.sync();this.e.resize();this.e.queueLive();}
 resize(w,h){if(!this.active||!this.data)return;const frame=applyShotViewport(this.e.camera,this.e.cut,this.e.cut.pageWidth,this.e.state,w,h);Object.assign(this.frame.style,{left:frame.x+'px',top:frame.y+'px',width:frame.w+'px',height:frame.h+'px'});}
 sync(){this.e.lens?.sync();const s=this.data;this.button.setAttribute('aria-pressed',String(this.active));this.helper.visible=!!s&&!this.active;if(!s)return;configureShot(this.helperCamera,s,this.aspect);this.helper.update();for(const c of Object.values(this.helper.pointMap))for(const i of c)this.helper.geometry.attributes.color.setXYZ(i,1,.65,.12);this.helper.geometry.attributes.color.needsUpdate=true;for(const [input,value]of [[this.inputs.focal,Number(s.focalLength.toFixed(1))],[this.inputs.fov,Number(shotFov(s,this.aspect).toFixed(1))],[this.inputs.fit,s.sensorFit],[this.inputs.size,s.sensorSize],[this.inputs.roll,Number((s.roll||0).toFixed(1))]])if(document.activeElement!==input)input.value=value;this.panel.querySelector('#shotView').textContent=this.active?'일반 화면으로':'카메라 화면';this.panel.querySelector('.shot-dimensions').textContent=`출력 · 현재 컷 ${Math.round(this.e.cut.pageWidth*this.e.cut.width/100)} × ${this.e.cut.height}px`;for(const {field,key,axis}of this.coords)if(document.activeElement!==field)field.value=Number(s[key][axis].toFixed(3));}
 render(){this.e.flush();this.e.advanced.export('all',Math.min(3000,Math.round(this.e.cut.pageWidth*this.e.cut.width/100)));}
}
